void handle_vm_cmdSelectSpecifiedCombatDeck(GameClient& cl, const uint8_t* body, size_t len)
{
    if (len < 2) return;
    uint16_t deckNo = rd16be(body, 0);
    applyLpc("cmd_select_specified_combat_deck", {make_int(cl.clientNo), make_int(deckNo)});
}

